{
  "cubeName": "sales_cube",
  "queryName": "average store cost by product family for USA stores in 1997",
  "aggregateFunction": "AVG",
  "measure": "store_cost",
  "gamma": [
    "product_dim.product_family"
  ],
  "sigma": [
    "store_dim.store_country = 'USA'",
    "date_dim.the_year = 1997"
  ]
}

{
  "cubeName": "sales_cube",
  "queryName": "average store cost by product family for stores in the USA during 1997",
  "aggregateFunction": "avg",
  "measure": "store_cost",
  "gamma": [
    "product_dim.product_family"
  ],
  "sigma": [
    "store_dim.store_country = 'USA'",
    "date_dim.the_year = 1997"
  ]
}

{
  "cubeName": "sales_cube",
  "queryName": "In 1997, how much sales revenue came from each product category under each type of promotional media?",
  "aggregateFunction": "sum",
  "measure": "store_sales",
  "gamma": [
    "product_dim.product_category",
    "promotion_dim.media_type"
  ],
  "sigma": [
    "date_dim.the_year = 1997"
  ]
}

{
  "cubeName": "sales_cube",
